import { tags } from "typia";

/**
 * Confirmation of the number of cart records successfully cleaned up and
 * deleted from the system. This response type is returned by the cleanup-expiry
 * operation after it has processed all expired carts based on the 30-day
 * inactivity policy.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICleanupResult = {
  /**
   * The number of cart records successfully cleaned up and deleted from the
   * system. This reflects the total count of expired carts (both
   * authenticated and guest) processed by the system cleanup job.
   */
  count: number & tags.Type<"int32">;
};
